Game Game::guardCombatInspection(int stage){
 auto authored=loadCustomCampaignFile(std::filesystem::path("custom maps")/"RawMetal-Ashfall-Exclusion-Zone.txt");auto campaign=std::make_shared<CustomCampaign>(*authored);auto map=std::make_shared<AuthoredMapData>(*campaign->maps[0]);if(map->actorTracks.empty()||!map->actorTracks[0].ai.armed)throw std::runtime_error("Custom playground has no authored armed guard");if(stage<0)map->actorTracks[0].ai.armed=false;campaign->maps[0]=map;Game g(campaign);
 if(stage>0){auto pose=g.npcActors()[0].pose;g.m_player.pos=pose.position+Vec2{2.3f,0};g.m_player.z=pose.z;bool reached=false;for(int i=0;i<240;++i){g.update({},1.f/60);if(stage==1?g.state(g.friendlyKey(0,"weapon_aim"))>=200:g.state(g.friendlyKey(0,"weapon_flash"))>0){reached=true;break;}}if(!reached)throw std::runtime_error("Custom playground guard did not reach aim/fire phase");}
 auto pose=g.npcActors()[0].pose;Vec2 camera=stage==3?pose.position+Vec2{0,-2.4f}:Vec2{21.5f,5.5f};if(!g.hullFits(camera,pose.z,Player::StandingHeight))throw std::runtime_error("Combat inspection camera intersects geometry");g.m_player.pos=camera;g.m_player.z=pose.z;g.m_player.angle=std::atan2(pose.position.y-camera.y,pose.position.x-camera.x);g.m_player.pitch=-8;g.m_weaponEquipped=false;g.m_holster=1;g.m_damageFlash=0;return g;
}
